fn error_handler_with_slot_workflow() -> Option<CompiledWorkflow> {
    let guard = CompiledNode {
        id: StepIdx::ZERO,
        output: None,
        next: None,
        on_error: None,
        error_slot: None,
        kind: CompiledNodeKind::ErrorHandler {
